-- 103_project_lessons_learned.sql
BEGIN;
CREATE TABLE IF NOT EXISTS public.project_lessons_learned_versions(id uuid PRIMARY KEY,project_id bigint NOT NULL REFERENCES public.projects(id)ON DELETE RESTRICT,version_number integer NOT NULL CHECK(version_number>0),status text NOT NULL CHECK(status IN('DRAFT','CONFIRMED')),factual_summary jsonb NOT NULL CHECK(jsonb_typeof(factual_summary)='object'),went_well jsonb NOT NULL CHECK(jsonb_typeof(went_well)='array'),went_wrong jsonb NOT NULL CHECK(jsonb_typeof(went_wrong)='array'),change_next_time jsonb NOT NULL CHECK(jsonb_typeof(change_next_time)='array'),created_by uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,version_number));CREATE UNIQUE INDEX IF NOT EXISTS project_lessons_one_confirmed_idx ON public.project_lessons_learned_versions(project_id)WHERE status='CONFIRMED';CREATE OR REPLACE FUNCTION private.prevent_project_lessons_mutation()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN RAISE EXCEPTION'PROJECT_LESSONS_LEARNED_IMMUTABLE'USING ERRCODE='55000';END;$$;DROP TRIGGER IF EXISTS project_lessons_immutable ON public.project_lessons_learned_versions;CREATE TRIGGER project_lessons_immutable BEFORE UPDATE OR DELETE ON public.project_lessons_learned_versions FOR EACH ROW EXECUTE FUNCTION private.prevent_project_lessons_mutation();ALTER TABLE public.project_lessons_learned_versions ENABLE ROW LEVEL SECURITY;DROP POLICY IF EXISTS project_lessons_select ON public.project_lessons_learned_versions;CREATE POLICY project_lessons_select ON public.project_lessons_learned_versions FOR SELECT TO authenticated USING(public.can_access_project(project_id));REVOKE ALL ON TABLE public.project_lessons_learned_versions FROM PUBLIC,anon,authenticated,service_role;GRANT SELECT ON TABLE public.project_lessons_learned_versions TO authenticated;
CREATE OR REPLACE FUNCTION public.save_project_lessons_learned(p_project_id bigint,p_lesson_id uuid,p_went_well jsonb,p_went_wrong jsonb,p_change_next_time jsonb,p_confirm boolean,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE u uuid:=auth.uid();role_name text;req public.write_command_requests%ROWTYPE;facts jsonb;version_no integer;state text;result jsonb;BEGIN SELECT upper(role)INTO role_name FROM public.profiles WHERE id=u;IF u IS NULL OR role_name NOT IN('PM','ADMIN')OR public.can_write_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PROJECT_LESSONS_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_lesson_id IS NULL OR p_client_request_id IS NULL OR jsonb_typeof(p_went_well)<>'array'OR jsonb_array_length(p_went_well)=0 OR jsonb_typeof(p_went_wrong)<>'array'OR jsonb_array_length(p_went_wrong)=0 OR jsonb_typeof(p_change_next_time)<>'array'OR jsonb_array_length(p_change_next_time)=0 THEN RAISE EXCEPTION'INVALID_PROJECT_LESSONS'USING ERRCODE='22023';END IF;INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(u,'project_closeout.lessons.save',p_client_request_id,p_project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT*INTO req FROM public.write_command_requests WHERE actor_id=u AND operation='project_closeout.lessons.save'AND client_request_id=p_client_request_id;IF req.response IS NOT NULL THEN RETURN req.response||jsonb_build_object('idempotentReplay',true);END IF;IF EXISTS(SELECT 1 FROM public.project_lessons_learned_versions WHERE project_id=p_project_id AND status='CONFIRMED')THEN RAISE EXCEPTION'PROJECT_LESSONS_ALREADY_CONFIRMED'USING ERRCODE='55000';END IF;
facts:=jsonb_build_object('cost',(SELECT to_jsonb(c)-'id'-'created_by'FROM public.project_cost_closeout_versions c WHERE c.project_id=p_project_id ORDER BY c.version_number DESC LIMIT 1),'schedule',(SELECT to_jsonb(s)-'id'-'created_by'FROM public.project_schedule_closeout_versions s WHERE s.project_id=p_project_id ORDER BY s.version_number DESC LIMIT 1),'scope',(SELECT jsonb_build_object('originalCount',jsonb_array_length(original_scope),'addedCount',jsonb_array_length(added_scope),'removedCount',jsonb_array_length(removed_scope),'changedCount',jsonb_array_length(changed_scope))FROM public.project_scope_closeout_versions WHERE project_id=p_project_id ORDER BY version_number DESC LIMIT 1),'quality',(SELECT jsonb_build_object('totalSnags',total_snags,'criticalSnags',critical_snags,'openAtHandover',open_at_handover,'reopenRate',reopen_rate)FROM public.project_quality_closeout_versions WHERE project_id=p_project_id ORDER BY version_number DESC LIMIT 1),'variations',(SELECT jsonb_build_object('proposed',total_proposed_count,'approved',approved_count,'rejected',rejected_count,'approvedValue',final_approved_variation_value)FROM public.project_variation_closeout_versions WHERE project_id=p_project_id ORDER BY version_number DESC LIMIT 1),'payments',(SELECT jsonb_build_object('contractValue',contract_value,'certifiedValue',certified_value,'paidValue',paid_value,'retentionHeld',retention_held,'outstandingValue',outstanding_value)FROM public.project_payment_closeout_versions WHERE project_id=p_project_id ORDER BY version_number DESC LIMIT 1));SELECT COALESCE(max(version_number),0)+1 INTO version_no FROM public.project_lessons_learned_versions WHERE project_id=p_project_id;state:=CASE WHEN COALESCE(p_confirm,false)THEN'CONFIRMED'ELSE'DRAFT'END;INSERT INTO public.project_lessons_learned_versions VALUES(p_lesson_id,p_project_id,version_no,state,facts,p_went_well,p_went_wrong,p_change_next_time,u,now());result:=jsonb_build_object('lessonId',p_lesson_id,'versionNumber',version_no,'status',state,'factualSummary',facts);UPDATE public.write_command_requests SET response=result,completed_at=now()WHERE id=req.id;RETURN result||jsonb_build_object('idempotentReplay',false);END;$$;
CREATE OR REPLACE FUNCTION public.get_project_lessons_learned(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$DECLARE x public.project_lessons_learned_versions%ROWTYPE;BEGIN IF auth.uid()IS NULL OR public.can_access_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PROJECT_LESSONS_FORBIDDEN'USING ERRCODE='42501';END IF;SELECT*INTO x FROM public.project_lessons_learned_versions WHERE project_id=p_project_id ORDER BY version_number DESC LIMIT 1;RETURN jsonb_build_object('projectId',p_project_id,'hasLessons',x.id IS NOT NULL,'lessons',CASE WHEN x.id IS NULL THEN NULL ELSE jsonb_build_object('lessonId',x.id,'versionNumber',x.version_number,'status',x.status,'factualSummary',x.factual_summary,'wentWell',x.went_well,'wentWrong',x.went_wrong,'changeNextTime',x.change_next_time,'createdAt',x.created_at)END);END;$$;REVOKE ALL ON FUNCTION private.prevent_project_lessons_mutation()FROM PUBLIC,anon,authenticated,service_role;REVOKE ALL ON FUNCTION public.save_project_lessons_learned(bigint,uuid,jsonb,jsonb,jsonb,boolean,uuid),public.get_project_lessons_learned(bigint)FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.save_project_lessons_learned(bigint,uuid,jsonb,jsonb,jsonb,boolean,uuid),public.get_project_lessons_learned(bigint)TO authenticated;COMMIT;
